#!/usr/bin/env bash
# Prints the Homebrew formula for a release.
# Usage: homebrew-formula.sh VERSION MACOS_SHA256 LINUX_SHA256
set -euo pipefail

version="$1"
macos_sha="$2"
linux_sha="$3"
base="https://github.com/vangheem/dumbot/releases/download/v${version}"

cat <<EOF
# Generated by vangheem/dumbot's release workflow; edits here are overwritten.
class Dumbot < Formula
  desc "Self-rewriting markdown bots that run on a schedule through opencode"
  homepage "https://github.com/vangheem/dumbot"
  version "${version}"
  license "MIT"

  on_macos do
    url "${base}/dumbot-macos-universal.tar.gz"
    sha256 "${macos_sha}"
  end

  on_linux do
    on_intel do
      url "${base}/dumbot-linux-x86_64.tar.gz"
      sha256 "${linux_sha}"
    end
  end

  def install
    bin.install "dumbot"
  end

  def caveats
    <<~EOS
      dumBot runs bots through opencode v2: https://opencode.ai
      Browser automation uses the browse MCP server, configured in opencode.

      On macOS, add dumbot to ~/Applications (Spotlight, Launchpad, Dock) with:
        dumbot install-app
      dumbot also offers to do this the first time you run it.
    EOS
  end

  test do
    assert_match "demo", shell_output("#{bin}/dumbot --list-scenes")
  end
end
EOF
